<script setup>
import axios from 'axios';
import { onMounted, ref } from 'vue';
import { RouterLink } from 'vue-router';

import { formatRupiah } from '../../utils/money';
const props = defineProps({ workspaceId: { type: [String, Number], required: true } });
const data = ref(null); const loading = ref(true); const error = ref('');
function dateLabel(value) { return value ? new Date(`${String(value).slice(0,10)}T12:00:00Z`).toLocaleDateString('id-ID',{timeZone:'UTC',day:'numeric',month:'short',year:'numeric'}) : 'Tanggal menyusul'; }
async function load() { loading.value=true; error.value=''; try { data.value=(await axios.get(`/api/workspaces/${props.workspaceId}/finance`)).data.summary; } catch { error.value='Ringkasan keuangan belum berhasil dimuat.'; } finally { loading.value=false; } }
onMounted(load);
</script>

<template>
    <section class="finance-home" aria-labelledby="finance-title">
        <header class="finance-home__head"><div><p class="eyebrow"><span class="eyebrow__dot"></span> RENCANA DAN CATATAN DANA</p><h1 id="finance-title">Keuangan bersama</h1><p>Lihat keadaan dana, rencana anggaran, dan tabungan dalam satu ringkasan.</p></div><RouterLink class="button button--primary" to="/app/transactions"><FaIcon :icon="['fas','plus']" /> Catat transaksi</RouterLink></header>
        <div v-if="loading" class="home-skeleton"><div class="skeleton-line skeleton-line--title"></div><div class="skeleton-row"><div class="skeleton-block"></div><div class="skeleton-block"></div></div></div>
        <div v-else-if="error" class="page-error" role="alert"><p>{{ error }}</p><button class="button button--quiet" @click="load">Coba lagi</button></div>
        <template v-else>
            <section class="finance-metrics"><article><span>SALDO SEMUA AKUN</span><strong>{{ formatRupiah(data.balance) }}</strong><small>Dihitung dari saldo awal dan mutasi aktif</small></article><article><span>PEMASUKAN</span><strong>{{ formatRupiah(data.income) }}</strong><small>Akumulasi mutasi pemasukan</small></article><article><span>PENGELUARAN</span><strong>{{ formatRupiah(data.expense) }}</strong><small>Akumulasi mutasi pengeluaran</small></article><article><span>PROGRES TABUNGAN</span><strong>{{ formatRupiah(data.saved) }} <small>dari {{ formatRupiah(data.savings_target) }}</small></strong><small>{{ data.savings_target ? Math.min(100,Math.round(data.saved/data.savings_target*100)) : 0 }}% dari target</small></article><article class="finance-metric--asset"><span>ASET NON-TUNAI</span><strong>{{ formatRupiah(data.assets_estimated_value) }}</strong><small>Estimasi terpisah dari saldo dan tabungan</small></article></section>
            <section class="finance-shortcuts"><RouterLink to="/app/accounts"><span class="finance-shortcut__icon"><FaIcon :icon="['fas','wallet']" /></span><span><strong>Akun</strong><small>Kelola kas dan rekening</small></span><FaIcon :icon="['fas','arrow-right']" /></RouterLink><RouterLink to="/app/transactions"><span class="finance-shortcut__icon"><FaIcon :icon="['fas','money-bill-wave']" /></span><span><strong>Transaksi</strong><small>Lihat mutasi dan transfer</small></span><FaIcon :icon="['fas','arrow-right']" /></RouterLink><RouterLink to="/app/budgets"><span class="finance-shortcut__icon"><FaIcon :icon="['fas','chart-pie']" /></span><span><strong>Anggaran</strong><small>Rencana dibanding realisasi</small></span><FaIcon :icon="['fas','arrow-right']" /></RouterLink><RouterLink to="/app/savings"><span class="finance-shortcut__icon"><FaIcon :icon="['fas','heart']" /></span><span><strong>Tabungan</strong><small>Target dan histori setoran</small></span><FaIcon :icon="['fas','arrow-right']" /></RouterLink><RouterLink to="/app/assets"><span class="finance-shortcut__icon"><FaIcon :icon="['fas','gem']" /></span><span><strong>Aset</strong><small>Barang dan estimasi nilainya</small></span><FaIcon :icon="['fas','arrow-right']" /></RouterLink></section>
            <section class="finance-home__lower"><article class="finance-home__budget"><div><p class="eyebrow">ANGGARAN</p><h2>Rencana dan realisasi</h2></div><div class="finance-home__budget-values"><span><small>Rencana</small><strong>{{ formatRupiah(data.planned_budget) }}</strong></span><span><small>Realisasi</small><strong>{{ formatRupiah(data.actual_budget) }}</strong></span></div><RouterLink class="text-link" to="/app/budgets">Buka anggaran <FaIcon :icon="['fas','arrow-right']" /></RouterLink></article><article class="finance-home__payments"><div><p class="eyebrow">PEMBAYARAN</p><h2>Jatuh tempo berikutnya</h2></div><RouterLink v-for="item in data.upcoming_payments" :key="item.id" class="finance-payment" to="/app/budgets"><span><strong>{{ item.title }}</strong><small>{{ dateLabel(item.due_at) }}</small></span><b>{{ formatRupiah(item.total_amount) }}</b></RouterLink><p v-if="!data.upcoming_payments.length" class="finance-no-payments">Belum ada kewajiban pembayaran terjadwal.</p><RouterLink class="text-link" to="/app/budgets">Kelola pembayaran <FaIcon :icon="['fas','arrow-right']" /></RouterLink></article></section>
        </template>
    </section>
</template>

